172e190c7 ftp: add extra buffer length check
 lib/ftp.c | 7 ++++---
 1 file changed, 4 insertions(+), 3 deletions(-)
commit 172e190c798645b9d04dd97ae0cf51b35317971e
Author: Daniel Stenberg <daniel@haxx.se>
Date:   Mon Oct 6 10:11:30 2025 +0200

    ftp: add extra buffer length check

    This adds an extra check that the buffer really has data enough (at
    least 4 bytes) to check for a status code before doing so. It *should*
    not be necessary, but this was pointed out by an analyzer and it feels
    better to make sure.

    Reported-by: Joshua Rogers
    Closes #18869

diff --git a/lib/ftp.c b/lib/ftp.c
index 10a61d368..77db98c00 100644
--- a/lib/ftp.c
+++ b/lib/ftp.c
@@ -402,167 +402,168 @@ static CURLcode ftp_cw_lc_write(struct Curl_easy *data,
     ctx->newline_pending = TRUE;
   }

   /* Any remaining data does not contain a '\r' */
   if(blen) {
     DEBUGASSERT(!ctx->newline_pending);
     return Curl_cwriter_write(data, writer->next, type, buf, blen);
   }
   else if(type & CLIENTWRITE_EOS) {
     /* EndOfStream, if we have a trailing cr, now is the time to write it */
     if(ctx->newline_pending) {
       ctx->newline_pending = FALSE;
       return Curl_cwriter_write(data, writer->next, type, &nl, 1);
     }
     /* Always pass on the EOS type indicator */
     return Curl_cwriter_write(data, writer->next, type, buf, 0);
   }
   return CURLE_OK;
 }

 static const struct Curl_cwtype ftp_cw_lc = {
   "ftp-lineconv",
   NULL,
   Curl_cwriter_def_init,
   ftp_cw_lc_write,
   Curl_cwriter_def_close,
   sizeof(struct ftp_cw_lc_ctx)
 };

 #endif /* CURL_PREFER_LF_LINEENDS */

 static CURLcode getftpresponse(struct Curl_easy *data, ssize_t *nread,
                                int *ftpcode);

 /***********************************************************************
  *
  * ftp_check_ctrl_on_data_wait()
  *
  */
 static CURLcode ftp_check_ctrl_on_data_wait(struct Curl_easy *data,
                                             struct ftp_conn *ftpc)
 {
   struct connectdata *conn = data->conn;
   curl_socket_t ctrl_sock = conn->sock[FIRSTSOCKET];
   struct pingpong *pp = &ftpc->pp;
   ssize_t nread;
   int ftpcode;
   bool response = FALSE;

   /* First check whether there is a cached response from server */
   if(curlx_dyn_len(&pp->recvbuf) && (*curlx_dyn_ptr(&pp->recvbuf) > '3')) {
     /* Data connection could not be established, let's return */
     infof(data, "There is negative response in cache while serv connect");
     (void)getftpresponse(data, &nread, &ftpcode);
     return CURLE_FTP_ACCEPT_FAILED;
   }

   if(pp->overflow)
     /* there is pending control data still in the buffer to read */
     response = TRUE;
   else {
     int socketstate = Curl_socket_check(ctrl_sock, CURL_SOCKET_BAD,
                                         CURL_SOCKET_BAD, 0);
     /* see if the connection request is already here */
     switch(socketstate) {
     case -1: /* error */
       /* let's die here */
       failf(data, "Error while waiting for server connect");
       return CURLE_FTP_ACCEPT_FAILED;
     default:
       if(socketstate & CURL_CSELECT_IN)
         response = TRUE;
       break;
     }
   }

   if(response) {
     infof(data, "Ctrl conn has data while waiting for data conn");
     if(pp->overflow > 3) {
       const char *r = curlx_dyn_ptr(&pp->recvbuf);
+      size_t len = curlx_dyn_len(&pp->recvbuf);

-      DEBUGASSERT((pp->overflow + pp->nfinal) <=
-                  curlx_dyn_len(&pp->recvbuf));
+      DEBUGASSERT((pp->overflow + pp->nfinal) <= curlx_dyn_len(&pp->recvbuf));
       /* move over the most recently handled response line */
       r += pp->nfinal;
+      len -= pp->nfinal;

-      if(LASTLINE(r)) {
+      if((len > 3) && LASTLINE(r)) {
         curl_off_t status;
         if(!curlx_str_number(&r, &status, 999) && (status == 226)) {
           /* funny timing situation where we get the final message on the
              control connection before traffic on the data connection has been
              noticed. Leave the 226 in there and use this as a trigger to read
              the data socket. */
           infof(data, "Got 226 before data activity");
           return CURLE_OK;
         }
       }
     }

     (void)getftpresponse(data, &nread, &ftpcode);

     infof(data, "FTP code: %03d", ftpcode);

     if(ftpcode/100 > 3)
       return CURLE_FTP_ACCEPT_FAILED;

     return CURLE_WEIRD_SERVER_REPLY;
   }

   return CURLE_OK;
 }

 /***********************************************************************
  *
  * ftp_initiate_transfer()
  *
  * After connection from server is accepted this function is called to
  * setup transfer parameters and initiate the data transfer.
  *
  */
 static CURLcode ftp_initiate_transfer(struct Curl_easy *data,
                                       struct ftp_conn *ftpc)
 {
   CURLcode result = CURLE_OK;
   bool connected;

   CURL_TRC_FTP(data, "ftp_initiate_transfer()");
   result = Curl_conn_connect(data, SECONDARYSOCKET, TRUE, &connected);
   if(result || !connected)
     return result;

   if(ftpc->state_saved == FTP_STOR) {
     /* When we know we are uploading a specified file, we can get the file
        size prior to the actual upload. */
     Curl_pgrsSetUploadSize(data, data->state.infilesize);

     /* set the SO_SNDBUF for the secondary socket for those who need it */
     Curl_sndbuf_init(data->conn->sock[SECONDARYSOCKET]);

     /* FTP upload, shutdown DATA, ignore shutdown errors, as we rely
      * on the server response on the CONTROL connection. */
     Curl_xfer_setup_send(data, SECONDARYSOCKET);
     Curl_xfer_set_shutdown(data, TRUE, TRUE);
   }
   else {
     /* FTP download, shutdown, do not ignore errors */
     Curl_xfer_setup_recv(data, SECONDARYSOCKET, ftpc->retr_size_saved);
     Curl_xfer_set_shutdown(data, TRUE, FALSE);
   }

   ftpc->pp.pending_resp = TRUE; /* expect server response */
   ftp_state(data, ftpc, FTP_STOP);

   return CURLE_OK;
 }

 static bool ftp_endofresp(struct Curl_easy *data, struct connectdata *conn,
                           const char *line, size_t len, int *code)
 {
   curl_off_t status;
   (void)data;
   (void)conn;

   if((len > 3) && LASTLINE(line) && !curlx_str_number(&line, &status, 999)) {
     *code = (int)status;
     return TRUE;
   }
